class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.cache = new Map();
    }

    get(key) {
        if (!this.cache.has(key)) return -1;
        const val = this.cache.get(key);
        this.cache.delete(key);
        this.cache.set(key, val);
        return val;
    }

    put(key, value) {
        if (this.cache.has(key)) {
            this.cache.delete(key);
        } else if (this.cache.size >= this.capacity) {
            const oldestKey = this.cache.keys().next().value;
            this.cache.delete(oldestKey);
        }
        this.cache.set(key, value);
    }
}

const lru = new LRUCache(2);
lru.put(1, 'Course A');
lru.put(2, 'Course B');
console.log("Get Key 1:", lru.get(1)); // returns Course A
lru.put(3, 'Course C');              // evicts key 2
console.log("Get Key 2 (Evicted):", lru.get(2)); // returns -1
lru.put(4, 'Course D');              // evicts key 1
console.log("Get Key 1 (Evicted):", lru.get(1)); // returns -1
console.log("Get Key 3:", lru.get(3)); // returns Course C
console.log("Get Key 4:", lru.get(4)); // returns Course D
